// dir (created with tempPattern), and returns the path of the named blueprint
// subdirectory plus a cleanup func that removes the temp dir.
func DownloadBlueprint(ctx context.Context, gh *GitHub, owner, repo, tag, templateName, tempPattern string) (string, func(), error) {
	return downloadBlueprint(ctx, gh, owner, repo, tag, templateName, tempPattern)
}

func downloadBlueprint(ctx context.Context, gh *GitHub, owner, repo, tag, templateName, tempPattern string) (string, func(), error) {
	rc, err := gh.Tarball(ctx, owner, repo, tag)
	if err != nil {
		return "", nil, err
	}
	defer rc.Close()

	tmpDir, err := os.MkdirTemp("", tempPattern)
	if err != nil {
		return "", nil, err
	}
	cleanup := func() { _ = os.RemoveAll(tmpDir) }

	if err := ExtractTarGz(rc, tmpDir); err != nil {
		cleanup()
		return "", nil, err
	}

	blueprintRoot := filepath.Join(tmpDir, templateName)
	if info, err := os.Stat(blueprintRoot); err != nil || !info.IsDir() {
		cleanup()
		return "", nil, fmt.Errorf("template %q not found in %s/%s@%s", templateName, owner, repo, tag)
	}
	return blueprintRoot, cleanup, nil

